CREATE TABLE IF NOT EXISTS gis_phase356_boundary_drift (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_a TEXT NOT NULL, source_b TEXT NOT NULL, feature_id TEXT NOT NULL, state_a TEXT, state_b TEXT, centroid_distance DOUBLE PRECISION, area_ratio DOUBLE PRECISION, bbox_distance DOUBLE PRECISION, classification TEXT NOT NULL, evidence JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_a,source_b,feature_id));